script:
frappe.ui.form.on('Tenant', {
    refresh(frm) {
        const call = (method) => {
            return frappe.call({
                method: 'songa_multi_tenancy.api.v1.tenants.' + method,
                args: { tenant: frm.doc.name },
            }).then(() => frm.reload_doc());
        };

        const confirm_call = (label, method) => {
            frappe.confirm(label, () => call(method));
        };

        if (frm.doc.status === 'Active') {
            frm.add_custom_button(__('Suspend'), () => {
                confirm_call(
                    __('Suspend this tenant? Its users will lose access until reactivated.'),
                    'suspend_tenant'
                );
            }, __('Actions'));

            frm.add_custom_button(__('Pause'), () => {
                confirm_call(
                    __('Pause this tenant? Its users will lose access until reactivated.'),
                    'pause_tenant'
                );
            }, __('Actions'));
        }

        if (['Suspended', 'Paused', 'Pending', 'Archived', 'Deleted'].includes(frm.doc.status)) {
            frm.add_custom_button(__('Activate'), () => {
                call('activate_tenant');
            }, __('Actions'));
        }

        if (!['Archived', 'Deleted'].includes(frm.doc.status)) {
            frm.add_custom_button(__('Archive'), () => {
                confirm_call(
                    __('Archive this tenant? Its users will lose access.'),
                    'archive_tenant'
                );
            }, __('Actions'));
        }

        if (frm.doc.status !== 'Deleted') {
            frm.add_custom_button(__('Delete Tenant'), () => {
                frappe.confirm(
                    __('Mark this tenant as deleted? Its users will be disabled and unable to log in. Data is preserved.'),
                    () => call('delete_tenant')
                );
            }, __('Actions'));
        }
    }
});

frappe.ui.form.on('Supplier Group', {
    refresh(frm) {
        frappe.call({
            method: 'songa_multi_tenancy.api.v1.tenants.current_tenant',
        }).then((r) => {
            const tenant = r.message;

            // Platform admins and tenant-less users see all parents.
            if (!tenant) {
                return;
            }

            // frappe.get_list already applies permission_query_conditions,
            // so this returns only the user's tenant groups.
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Supplier Group',
                    fields: ['name'],
                    limit_page_length: 0,
                },
            }).then((res) => {
                const names = (res.message || []).map((d) => d.name);

                // The tree root belongs to SYSTEM and is shared.
                if (!names.includes('All Supplier Groups')) {
                    names.push('All Supplier Groups');
                }

                frm.set_query('parent_supplier_group', () => ({
                    filters: [['name', 'in', names]],
                }));
            });
        });
    }
});

frappe.ui.form.on('Item Group', {
    refresh(frm) {
        frappe.call({
            method: 'songa_multi_tenancy.api.v1.tenants.current_tenant',
        }).then((r) => {
            const tenant = r.message;
            if (!tenant) { return; }
            frappe.call({
                method: 'frappe.client.get_list',
                args: { doctype: 'Item Group', fields: ['name'], limit_page_length: 0 },
            }).then((res) => {
                const names = (res.message || []).map((d) => d.name);
                if (!names.includes('All Item Groups')) { names.push('All Item Groups'); }
                frm.set_query('parent_item_group', () => ({
                    filters: [['name', 'in', names]],
                }));
            });
        });
    }
});

